/** Criterion types with no `modifier` field, emitting one is a 422. */
export const CRITERIA_WITHOUT_MODIFIER = new Set(["DuplicationCriterionInput","FileDuplicationCriterionInput","OrientationCriterionInput"]);

/** Criterion types whose `value` is a list, a bare scalar must be wrapped. */
export const LIST_VALUED_CRITERIA = new Set(["CircumcisionCriterionInput","CustomFieldCriterionInput","HierarchicalMultiCriterionInput","MultiCriterionInput","OrientationCriterionInput"]);

/**
 * criterionTypeName → its declared field names.
 *
 * The translator prunes anything it emits that this list does not declare.
 * That is what keeps a stray key (the clearest example being `depth`, which
 * only the Hierarchical variants accept) from turning the whole request into
 * an opaque 422.
 */
export const CRITERION_FIELDS = {
  CircumcisionCriterionInput: ['modifier', 'value'],
  CustomFieldCriterionInput: ['field', 'modifier', 'value'],
  DateCriterionInput: ['modifier', 'value', 'value2'],
  DuplicationCriterionInput: ['distance', 'duplicated', 'phash', 'stash_id', 'title', 'url'],
  FileDuplicationCriterionInput: ['distance', 'duplicated', 'phash'],
  FloatCriterionInput: ['modifier', 'value', 'value2'],
  GenderCriterionInput: ['modifier', 'value', 'value_list'],
  HierarchicalMultiCriterionInput: ['depth', 'excludes', 'modifier', 'value'],
  IntCriterionInput: ['modifier', 'value', 'value2'],
  MultiCriterionInput: ['excludes', 'modifier', 'value'],
  OrientationCriterionInput: ['value'],
  PhashDistanceCriterionInput: ['distance', 'modifier', 'value'],
  ResolutionCriterionInput: ['modifier', 'value'],
  StashIDCriterionInput: ['endpoint', 'modifier', 'stash_id'],
  StashIDsCriterionInput: ['endpoint', 'modifier', 'stash_ids'],
  StringCriterionInput: ['modifier', 'value'],
  TimestampCriterionInput: ['modifier', 'value', 'value2'],
};

/** Type names that are themselves nested filters (recurse into them). */
export const FILTER_TYPE_NAMES = new Set(Object.keys(FILTER_TYPES));

/**
 * Enum name → its values, for every enum a criterion declares as its
 * `modifier` or `value`. `CriterionModifier` is here because every criterion
 * declares its `modifier` as that one enum; the rest are the value enums
 * (`ResolutionEnum`, `GenderEnum`, …).
 *
 * Captured rather than hardcoded for the same reason the field map is: the
 * set of legal modifiers is per-criterion-type, and a hardcoded list is how
 * a translator bug becomes a 422 nobody can read.
 */
export const ENUMS = {
  CircumcisedEnum: ['CUT', 'UNCUT'],
  CriterionModifier: ['BETWEEN', 'EQUALS', 'EXCLUDES', 'GREATER_THAN', 'INCLUDES', 'INCLUDES_ALL', 'IS_NULL', 'LESS_THAN', 'MATCHES_REGEX', 'NOT_BETWEEN', 'NOT_EQUALS', 'NOT_MATCHES_REGEX', 'NOT_NULL'],
  GenderEnum: ['FEMALE', 'INTERSEX', 'MALE', 'NON_BINARY', 'TRANSGENDER_FEMALE', 'TRANSGENDER_MALE'],
  ResolutionEnum: ['EIGHT_K', 'FIVE_K', 'FOUR_K', 'FULL_HD', 'HUGE', 'LOW', 'QUAD_HD', 'R360P', 'SEVEN_K', 'SIX_K', 'STANDARD', 'STANDARD_HD', 'VERY_LOW', 'WEB_HD'],
};
